D=data/cases/scotus/73500236/record/blinded/codex-baseline && for f in reasoning.md predicted_reasoning.md retrieval.md; do echo "===== $f"; cat $D/$f; echo; done; echo "===== retrieval_log.json"; python3 -c "
import json;d=json.load(open('$D/retrieval_log.json'))
print({k:v for k,v in d.items() if k!='calls'})
for c in d.get('calls',[]): print(json.dumps({k:c.get(k) for k in ('tool_class','query','retrieved_doc_date','result_capture','result_status','timestamp') if k in c})[:400])
"

